{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    edges = []
    for u, v, d in distances:
        w = max(core[u], core[v], d)
        if u <= v:
            edges.append((u, v, w))
        else:
            edges.append((v, u, w))
    edges.sort(key=lambda x: (x[2], x[0], x[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True
    mst_edges = []
    total = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Disconnected graph - cannot form MST')
    return {'mst_edges': mst_edges, 'total_weight': total}"
}
